import { useState } from 'react'

const Button = ({clickHandle, text}) => (
  <button onClick={clickHandle}> {text} </button>

)
const Statistics = (props) => {
  if (props.good || props.neutral || props.bad == 0){
    return (
      <div>
        <h1>statistics</h1>
        <p>No feedback given</p>
      </div>
    )
  }
  return (
    <div>
      <h1>statistics</h1>
      <ul>
        <li>good {props.good}</li>
        <li>neutral {props.neutral}</li>
        <li>bad {props.bad}</li>
        <li>total {props.total}</li>
        <li>average {(props.good - props.bad)/props.total}</li>
        <li>positive {(props.good/props.total)*100}</li>
      </ul>
    </div>

  )
}
const App = () => {
  // salve os cliques de cada botão em seu próprio estado
  const [good, setGood] = useState(0)
  const [neutral, setNeutral] = useState(0)
  const [bad, setBad] = useState(0)
  const total = good + neutral + bad
  return (
    <>
      <div>
        <h1>give feedback</h1>
        <Button clickHandle={() => setGood(good + 1)} text="good"/>
        <Button clickHandle={() => setNeutral(neutral + 1)} text="neutral"/>
        <Button clickHandle={() => setBad(bad + 1)} text="bad"/>
        <Statistics good = {good} neutral = {neutral} bad = {bad} total = {total}/>
      </div>
    </>
  )
}

export default App
